    # A creator vetting, including its analysis runs and request settings.
    class CreatorVetting
      # Identifier of the vetting
      field :id, "id"
      # Time the vetting was created (UTC, ISO-8601)
      field :created_at, "created_at", cast: :time
      # Time the vetting was most recently modified (UTC, ISO-8601)
      field :updated_at, "updated_at", cast: :time
      # Identifier of the creator the vetting is tied to
      field :creator_id, "creator_id"
      # Status of the vetting
      field :status, "status"
      # The creator tied to this vetting
      field :creator, "creator", cast: Creator
      # Always CREATOR_ANALYSIS here
      field :type, "type"
      # Identifier of the scrape job triggered for this request
      field :sync_job_id, "sync_job_id"
      # The analysis runs tied to this vetting, ordered newest first
      field :analysis, "analysis", cast: [CreatorVettingRun]
      # The safety criteria submitted with this vetting request
      field :safety_checks, "safety_checks"
      # The content relationships analyzed for this creator
      field :content_scope, "content_scope"
    end

    # Request body for ``POST /api/v1/creator/vetting/``.
    class CreatorVettingRequest
      # When true, re-indexes the creator even if they already exist in our database
      field :resync_profile, "resync_profile"
      # Direct URL to the creator's profile on a supported platform (instagram, tiktok,...
      field :profile_url, "profile_url"
      # The creator's content relationships to analyze
      field :content_scope, "content_scope", cast: ContentScopeRequest
      # Safety criteria for the AI pipeline to evaluate for this creator
      field :safety_checks, "safety_checks", cast: [SafetyCheckRequest]
    end

    # An analysis run together with its downloadable ``result``. Returned by
    # `creator_vetting.results` for the analysis `creator_vetting.list` points to.
    class CreatorVettingResult
      # Identifier of the analysis record
      field :id, "id"
      # The subject this analysis covers: CONTENT or COMMENT
      field :scope, "scope"
      # Time the analysis was created (UTC, ISO-8601)
      field :created_at, "created_at", cast: :time
      # Time the analysis was most recently modified (UTC, ISO-8601)
      field :modified_at, "modified_at", cast: :time
      # Identifier of the vetting this analysis belongs to
      field :vetting_id, "vetting_id"
      # Status of the analysis
      field :status, "status"
      # Signed, time-limited download of the run's analysis payload
      field :result, "result", cast: ResultFile
    end

    # A lightweight analysis run that belongs to a vetting. This representation omits the
    # ``result``. Retrieve it from `creator_vetting.results` once ``status`` is
    # ``COMPLETED``.
    class CreatorVettingRun
      # Identifier of the analysis record
      field :id, "id"
      # The subject this analysis covers: CONTENT or COMMENT
      field :scope, "scope"
      # Status of the analysis
      field :status, "status"
    end

    # One brand placement detection run.
    class Detection
      # Identifier of the detection
      field :id, "id"
      # Time the detection was created (UTC, ISO-8601)
      field :created_at, "created_at", cast: :time
      # Time the detection was most recently modified (UTC, ISO-8601)
      field :updated_at, "updated_at", cast: :time
      # Where the detection has got to
      field :status, "status"
      # The input this detection was created with
      field :context, "context", cast: DetectionContext
      # The placements document
      field :result, "result", cast: DetectionResult
    end

    # One brand to look for, and what counts as evidence for it.
    class DetectionBrandHint
      # Display name of the brand, at most 60 characters
      field :name, "name"
      # 2 to 10 words, logos and product names that count as evidence of this brand, the...
      field :identifiers, "identifiers"
      # Up to 12 look-alikes that must not count, each at most 200 characters, for...
      field :negatives, "negatives"
    end

    # One brand to look for, and what counts as evidence for it.
    class DetectionBrandHintRequest
      # Display name of the brand, at most 60 characters
      field :name, "name"
      # 2 to 10 words, logos and product names that count as evidence of this brand, the...
      field :identifiers, "identifiers"
      # Up to 12 look-alikes that must not count, each at most 200 characters, for...
      field :negatives, "negatives"
    end

    # Everything found for one requested brand.
    class DetectionBrandResult
      # The requested brand, named exactly as it was asked for
      field :brand_name, "brand_name"
      # Whether the brand was present at all
      field :found, "found"
      # Counts for this brand
      field :summary, "summary", cast: DetectionBrandSummary
      # Every placement for this brand, earliest first
      field :placements, "placements", cast: [DetectionPlacement]
    end

    # Counts for one brand.
    class DetectionBrandSummary
      # Placements for this brand
      field :placements, "placements"
      # Of those, confirmed
      field :confirmed, "confirmed"
      # Of those, left for review
      field :review, "review"
    end

    # The input the detection run was given, as stored.
    class DetectionContext
      # URL of the content being analysed
      field :external_url, "external_url"
      # The brands to detect and the evidence that counts for each
      field :hints, "hints", cast: DetectionHints
    end

    # What the caller supplies as the detection's input.
    class DetectionContextInputRequest
      # The brands to detect and the evidence that counts for each
      field :hints, "hints", cast: DetectionHintsRequest
    end

    # Request body for ``POST /api/v1/detection/``.
    class DetectionCreateRequest
      # Identifier of content Zelf already holds, obtained from content.list
      field :content_id, "content_id"
      # Direct URL to the post or video to analyse
      field :content_url, "content_url"
      # The brands to detect and the evidence that counts for each
      field :context, "context", cast: DetectionContextInputRequest
    end

    # What the detector is asked to look for.
    class DetectionHints
      # 1 to 200 brands to detect, in the order the results report them
      field :brands, "brands", cast: [DetectionBrandHint]
    end

    # What the detector is asked to look for.
    class DetectionHintsRequest
      # 1 to 200 brands to detect, in the order the results report them
      field :brands, "brands", cast: [DetectionBrandHintRequest]
    end

    # One brand present in the content at one moment, with its evidence.
    class DetectionPlacement
      # mm:ss-mm:ss, or mm:ss for a single moment
      field :timestamp, "timestamp"
      # YouTube: opens the video 5 seconds before the placement
      field :video_url_at_timestamp, "video_url_at_timestamp"
      # How it was detected
      field :modality, "modality"
      # What was observed, in the detector's own words
      field :what_detected, "what_detected"
      # Why the observation counts as this brand
      field :reasoning, "reasoning"
      # confirmed: passed a final check against the video's frames
      field :confidence, "confidence"
    end

    # The placements document a finished detection produces.
    class DetectionResult
      # The content that was analysed
      field :video, "video", cast: DetectionVideo
      # Counts across the whole run
      field :summary, "summary", cast: DetectionSummary
      # One entry per requested brand, in request order, including the brands that were...
      field :brands, "brands", cast: [DetectionBrandResult]
    end

    # Counts across the whole run.
    class DetectionSummary
      # How many brands the rubric asked for
      field :brands_requested, "brands_requested"
      # How many of those brands were present
      field :brands_found, "brands_found"
      # Total placements reported
      field :placements, "placements"
      # Placements that passed the final frame check
      field :confirmed, "confirmed"
      # Placements that did not pass the final frame check, including every Audio placement
      field :review, "review"
    end

    # The content the placements were found in.
    class DetectionVideo
      # URL of the analysed content
      field :video_url, "video_url"
      # Platform the content was posted on
      field :platform, "platform"
      # Length of the content in seconds
      field :duration_s, "duration_s"
    end

    # Partial update for a brand's monitoring keywords. Every field is optional, and only
    # the supplied fields are changed, but at least one field is required.
    class PatchedBrandUpdateRequest
      # Plain keywords the brand monitors across platforms, matched as-is (case-...
      field :search_terms, "search_terms"
      # Terms that must be present for content to match
      field :inclusion_terms, "inclusion_terms"
      # Terms that disqualify content from matching
      field :exclusion_terms, "exclusion_terms"
      # Secondary inclusion terms layered on top of inclusion_terms
      field :compound_inclusion_terms, "compound_inclusion_terms"
      # Terms that mark matched content as influencer content
      field :influencer_terms, "influencer_terms"
      # ISO 639-1 codes to track, or the single value all
      field :allowed_languages, "allowed_languages"
      # Full-text search across the caption, transcript, summary, and hashtags
      field :boolean_query, "boolean_query"
      # Brand to update, specified as an id from brands.list
      field :brand_id, "brand_id"
    end

    # The PatchedWebhookSubscriptionUpdateRequest object.
    class PatchedWebhookSubscriptionUpdateRequest
      # Destination URL where webhook payloads are sent
      field :url, "url"
      # Filters that scope which resources are delivered
      field :resource_filters, "resource_filters"
      # Extra HTTP headers sent with each webhook request
      field :custom_headers, "custom_headers"
      # Hours between snapshot deliveries
      field :interval_hours, "interval_hours"
      # Maximum number of items per delivery
      field :max_items, "max_items"
      # Whether this subscription is active and will be dispatched
      field :enabled, "enabled"
    end

    # Signed, time-limited download of an analysis run's result payload.
    class ResultFile
      # Unix epoch seconds after which download_url expires
      field :expires_at, "expires_at"
      # Payload encoding
      field :format, "format"
      # Signed URL to request the JSON payload
      field :download_url, "download_url"
    end

    # A single safety criterion the AI pipeline evaluates against the creator. Only
    # ``type`` is required. The ``extra`` field supplies the label for the
    # ``USER_DEFINED_SAFETY_CRITERION`` type and is ignored for the predefined types.
    class SafetyCheckRequest
      # Category of the safety criterion
      field :type, "type"
      # Label for USER_DEFINED_SAFETY_CRITERION, stored as the criterion's value
      field :extra, "extra"
    end

    # Live consumption for the brand behind the current credentials.
    class Usage
      # Brand these figures belong to
      field :brand_id, "brand_id"
      # api_key or mcp, whichever made this call
      field :authenticated_as, "authenticated_as"
      # Keyed by group
      field :scopes, "scopes"
    end

    # One metered group, with every window that has a limit.
    class UsageScope
      # Name of the group, as an admin sees it
      field :human_name, "human_name"
      # request counts calls; item counts rows returned
      field :kind, "kind"
      # Which product the group meters: api for direct requests, mcp for AI clients
      field :section, "section"
      # Keyed by window: rps, rpm, rph, rpd, rpmonth, or the item windows
      field :windows, "windows"
    end

    # Consumption of one window, e.g. requests in the current hour.
    class UsageWindow
      # Most that may be spent in this window
      field :limit, "limit"
      # Spent so far in this window
      field :used, "used"
      # Still available in this window
      field :remaining, "remaining"
      # Seconds until the window resets
      field :reset_in, "reset_in"
    end

    # The WebhookAvailableEvent object.
    class WebhookAvailableEvent
      # Event type identifier, e.g
      field :event, "event"
      # Human-readable grouping label
      field :group, "group"
      # What triggers the event and what the payload holds
      field :description, "description"
    end

    # The carried content of a push. The populated key depends on `delivery_mode`.
    # `manifest` deliveries populate `files` (downloadable snapshot files) and, for the
    # content resource, `statistics`. `inline` deliveries populate `items` (the rows
    # directly). The unused key is omitted.
    class WebhookData
      # Total number of rows in this delivery, summed across files or equal to the length...
      field :item_count, "item_count"
      # Aggregate totals over the snapshot, including post count, views, engagement,...
      field :statistics, "statistics"
      # Manifest mode only
      field :files, "files", cast: [WebhookFile]
      # Inline mode only
      field :items, "items"
    end

    # The WebhookDeleteAcknowledgement object.
    class WebhookDeleteAcknowledgement
      # Always true; confirms the webhook resource delete was acknowledged
      field :acknowledged, "acknowledged"
      # Action that was performed
      field :action, "action"
      # Completion status of the action
      field :status, "status"
    end

    # The WebhookDelivery object.
    class WebhookDelivery
      # Encoded identifier of the webhook delivery
      field :id, "id"
      # Encoded identifier of the parent subscription
      field :subscription, "subscription"
      # When this delivery is scheduled to be sent
      field :scheduled_at, "scheduled_at", cast: :time
      # Number of delivery attempts made so far
      field :attempt_count, "attempt_count"
      # Current state of the delivery
      field :state, "state"
      # HTTP status code returned by the most recent attempt
      field :last_status_code, "last_status_code"
      # Error message from the most recent failed attempt
      field :last_error, "last_error"
      # Excerpt of the response body returned by the endpoint
      field :response_excerpt, "response_excerpt"
      # When the delivery finished (succeeded or exhausted)
      field :finished_at, "finished_at", cast: :time
      # Number of items included in the delivered payload
      field :item_count, "item_count"
      # SHA-256 checksum of the delivered payload
      field :sha256, "sha256"
      # Size of the delivered payload in bytes
      field :size_bytes, "size_bytes"
      # Timestamp set once when the row is first created
      field :created, "created", cast: :time
      # Timestamp updated automatically on every save
      field :modified, "modified", cast: :time
    end

    # One downloadable snapshot file in a manifest push. A delivery currently consists of
    # a single file, so `files` carries one entry. The array shape allows a snapshot to be
    # sharded across several files in the future without changing the envelope.
    class WebhookFile
      # File encoding
      field :format, "format"
      # Unix epoch seconds after which download_url stops working
      field :expires_at, "expires_at"
      # Hex SHA-256 of the file body
      field :sha256, "sha256"
      # Size of the file in bytes
      field :size_bytes, "size_bytes"
      # Number of rows in this file
      field :item_count, "item_count"
      # Signed, time-limited URL from which to retrieve the file
      field :download_url, "download_url"
    end

    # The outer payload ZelfAI POSTs to receivers, uniform across all pushes. Top-level
    # fields are delivery metadata and remain identical across modes. `data` carries the
    # content; which key inside it is populated (`files` or `items`) is determined by
    # `delivery_mode`. `manifest` deliveries use `data.files`, while `inline` event pushes
    # use `data.items`.
    class WebhookPush
      # Unique id of this delivery attempt, stable across retries of the same push
      field :id, "id"
      # Event type
      field :type, "type"
      # Id of the subscription that produced this push
      field :subscription_id, "subscription_id"
      # Unix epoch seconds at which ZelfAI sent this push
      field :delivered_at, "delivered_at"
      # true for production data; false for test deliveries
      field :livemode, "livemode"
      # Resource the push covers (content or creator) for snapshots; null for event pushes
      field :resource, "resource"
      # The subscription's stored filters that scoped this snapshot, using the same query...
      field :resource_filters, "resource_filters"
      # manifest: data.files holds downloadable snapshot files
      field :delivery_mode, "delivery_mode"
      # The push payload
      field :data, "data", cast: WebhookData
    end

    # The WebhookSecret object.
    class WebhookSecret
      # Encoded identifier of the webhook secret
      field :id, "id"
      # Type of webhook this secret applies to
      field :kind, "kind"
      # Non-sensitive prefix of the secret, shown for identification
      field :secret_prefix, "secret_prefix"
      # Whether this secret is currently active
      field :is_active, "is_active"
      # Whether this is the default secret for the brand and kind
      field :is_default, "is_default"
      # Timestamp set once when the row is first created
      field :created, "created", cast: :time
      # Timestamp updated automatically on every save
      field :modified, "modified", cast: :time
    end

    # The WebhookSecretCreateRequest object.
    class WebhookSecretCreateRequest
      # Whether the secret is for snapshot or event webhooks
      field :kind, "kind"
      # Set this secret as the default for its kind
      field :make_default, "make_default"
    end

    # The WebhookSecretCreated object.
    class WebhookSecretCreated
      # Encoded identifier of the webhook secret
      field :id, "id"
      # Type of webhook this secret applies to
      field :kind, "kind"
      # Non-sensitive prefix of the secret, shown for identification
      field :secret_prefix, "secret_prefix"
      # Whether this secret is currently active
      field :is_active, "is_active"
      # Whether this is the default secret for the brand and kind
      field :is_default, "is_default"
      # Timestamp set once when the row is first created
      field :created, "created", cast: :time
      # Timestamp updated automatically on every save
      field :modified, "modified", cast: :time
      # Full signing secret, returned only once on creation
      field :secret, "secret"
    end

    # The WebhookSubscription object.
    class WebhookSubscription
      # Encoded identifier of the webhook subscription
      field :id, "id"
      # Type of webhook this subscription delivers
      field :kind, "kind"
      # Resource type the subscription is for (content or creator)
      field :resource, "resource"
      # Event types the subscription listens for
      field :event_types, "event_types"
      # Filters applied to select which resources are delivered
      field :resource_filters, "resource_filters"
      # Destination URL where webhook payloads are sent
      field :url, "url"
      # Custom HTTP headers to include with each delivery
      field :custom_headers, "custom_headers"
      # Hours between snapshot deliveries
      field :interval_hours, "interval_hours"
      # Max rows a real snapshot delivers
      field :max_items, "max_items"
      # Public prefix of the subscription signing secret
      field :secret_prefix, "secret_prefix"
      # Whether this subscription is active and will be dispatched
      field :enabled, "enabled"
      # When this subscription last dispatched a delivery
      field :last_run_at, "last_run_at", cast: :time
      # Outcome status of the most recent delivery
      field :last_status, "last_status"
      # Timestamp set once when the row is first created
      field :created, "created", cast: :time
      # Timestamp updated automatically on every save
      field :modified, "modified", cast: :time
    end

    # The WebhookSubscriptionCreateRequest object.
    class WebhookSubscriptionCreateRequest
      # Whether the subscription is snapshot or event based
      field :kind, "kind"
      # Resource type for snapshot subscriptions
      field :resource, "resource"
      # Event names the subscription listens for
      field :event_types, "event_types"
      # Filters that scope which resources are delivered
      field :resource_filters, "resource_filters"
      # Destination URL where webhook payloads are sent
      field :url, "url"
      # Extra HTTP headers sent with each webhook request
      field :custom_headers, "custom_headers"
      # Hours between snapshot deliveries
      field :interval_hours, "interval_hours"
      # Maximum number of items per delivery
      field :max_items, "max_items"
      # Type of signing secret to attach to the subscription
      field :secret_type, "secret_type"
    end

    # The WebhookSubscriptionCreated object.
    class WebhookSubscriptionCreated
      # Encoded identifier of the webhook subscription
      field :id, "id"
      # Type of webhook this subscription delivers
      field :kind, "kind"
      # Resource type the subscription is for (content or creator)
      field :resource, "resource"
      # Event types the subscription listens for
      field :event_types, "event_types"
      # Filters applied to select which resources are delivered
      field :resource_filters, "resource_filters"
      # Destination URL where webhook payloads are sent
      field :url, "url"
      # Custom HTTP headers to include with each delivery
      field :custom_headers, "custom_headers"
      # Hours between snapshot deliveries
      field :interval_hours, "interval_hours"
      # Max rows a real snapshot delivers
      field :max_items, "max_items"
      # Public prefix of the subscription signing secret
      field :secret_prefix, "secret_prefix"
      # Full signing secret, returned only once, at the moment it is minted
      field :secret, "secret"
      # Whether this subscription is active and will be dispatched
      field :enabled, "enabled"
      # Timestamp set once when the row is first created
      field :created, "created", cast: :time
    end

  end
end
